template:
@php
    $layout = in_array($layout, ['grid', 'gallery', 'by-hand'], true) ? $layout : 'grid';
    $count = max(1, min(6, (int) ($pictures ?: 6)));
    // The pictures ship with the theme (assets/showcase): the page loads nothing from anywhere but
    // the site, and a link opens a real file without JavaScript.
    $theme = collect(app(\WebxUi\Themes\ThemeChain::class)->layers)->firstWhere('name', 'webx-ui/theme-default');
    $file = static fn (int $n): string => ($theme ? app(\WebxUi\Themes\ThemeAssets::class)->url($theme, "assets/showcase/photo-{$n}.svg", url()) : null) ?? "#photo-{$n}";
    // What a media field of the library resolves to: the sizes are stored at upload.
    $image = static fn (int $n): array => ['url' => $file($n), 'thumb' => null, 'alt' => "Photo {$n}", 'title' => null, 'width' => $n === 7 ? 1200 : 2400, 'height' => $n === 7 ? 2000 : 1600];
@endphp
<section class="b-showcase-lightbox b-showcase-lightbox--{{ $layout }}" data-wx-block="showcase-lightbox">
    @if ($heading)
        <h2 class="b-showcase-lightbox__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-lightbox__note">{{ $note }}</p>
    @endif
    @switch($layout)
        @case('gallery')
            <div class="b-showcase-lightbox__frame">
                <x-webx-slider variant="gallery" :label="$heading ?: null">
                    @for ($i = 1; $i <= $count; $i++)
                        <x-webx-slide>
                            <x-webx-lightbox :image="$image($i)" group="showcase-gallery">
                                <img class="b-showcase-lightbox__photo" src="{{ $file($i) }}" width="2400" height="1600" alt="Photo {{ $i }} of {{ $count }}">
                            </x-webx-lightbox>
                        </x-webx-slide>
                    @endfor
                </x-webx-slider>
            </div>
            @break
        @case('by-hand')
            <div class="b-showcase-lightbox__row">
                <a class="b-showcase-lightbox__tall" href="{{ $file(7) }}" data-webx-lightbox="" data-width="1200" data-height="2000"><img class="b-showcase-lightbox__photo" src="{{ $file(7) }}" width="1200" height="2000" alt="Photo 7, taller than wide"></a>
                <a class="b-showcase-lightbox__tall" href="{{ $file(5) }}" data-webx-lightbox=""><img class="b-showcase-lightbox__photo" src="{{ $file(5) }}" width="2400" height="1600" alt="Photo 5, a link without sizes"></a>
            </div>
            @break
        @default
            <ul class="b-showcase-lightbox__grid">
                @for ($i = 1; $i <= $count; $i++)
                    <li class="b-showcase-lightbox__cell"><x-webx-lightbox :image="$image($i)" group="showcase-grid" /></li>
                @endfor
            </ul>
    @endswitch
</section>

styles:
.b-showcase-lightbox {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
    container-type: inline-size;
}

.b-showcase-lightbox__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-lightbox__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-lightbox__grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--site-space-3);
    margin: 0;
    padding: 0;
    list-style: none;
}

@container (min-width: 40rem) {
    .b-showcase-lightbox__grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

.b-showcase-lightbox__cell {
    min-width: 0;
    border-radius: var(--site-radius-sm);
    overflow: hidden;
}

.b-showcase-lightbox__frame {
    max-width: 40rem;
}

.b-showcase-lightbox__row {
    display: flex;
    flex-wrap: wrap;
    gap: var(--site-space-3);
    align-items: flex-start;
}

.b-showcase-lightbox__tall {
    display: block;
    width: 10rem;
    max-width: 100%;
}

.b-showcase-lightbox__photo {
    display: block;
    width: 100%;
    height: auto;
    border-radius: var(--site-radius-sm);
}
